    fam_i5: 'En la nómina, un día de permiso retribuido (como la lactancia acumulada) cuenta como un día de vacaciones: 3:30 h de FDP y 1:12 h de servicio adicional (convenio, art. 24.5.2 c y 24.5.3 b).',
    fam_i4: 'Lactancia: hasta que el bebé cumpla 9 meses tienes 1 hora al día de ausencia retribuida, o media hora menos de jornada. En vuelo lo habitual es acumularla en días completos; el convenio no lo regula, así que se acuerda con la empresa. Si los dos progenitores la disfrutan igual, se puede alargar hasta los 12 meses con menos sueldo.',
    fam_i3: 'Embarazo: como TCP normalmente dejas de volar. Si la empresa no te puede dar un puesto en tierra, es una suspensión por riesgo durante el embarazo y la mutua paga el 100 % de la base reguladora (esta prestación sí lleva IRPF y Seguridad Social).',
    fam_i2: 'Durante el permiso Eurowings no paga el sueldo de esos días: el INSS paga el 100 % de tu base reguladora (base de cotización del mes anterior ÷ 30, por día), sin IRPF ni descuentos. Se pide en la sede electrónica de la Seguridad Social.',
