    fam_disc: 'És una estimació amb les regles del 2026. L’import exacte el calcula l’INSS: confirma-ho amb RRHH o amb la Seguretat Social.',
    fam_i5: 'A la nòmina, un dia de permís retribuït (com la lactància acumulada) compta com un dia de vacances: 3:30 h d’FDP i 1:12 h de servei addicional (conveni, art. 24.5.2 c i 24.5.3 b).',
    fam_i4: 'Lactància: fins que el nadó faci 9 mesos tens 1 hora al dia d’absència retribuïda, o mitja hora menys de jornada. En vol el normal és acumular-la en dies complets; el conveni no ho regula, així que s’acorda amb l’empresa. Si els dos progenitors la gaudeixen igual, es pot allargar fins als 12 mesos amb menys sou.',
    fam_i3: 'Embaràs: com a TCP normalment deixes de volar. Si l’empresa no et pot donar un lloc a terra, és una suspensió per risc durant l’embaràs i la mútua paga el 100 % de la base reguladora (aquesta prestació sí porta IRPF i Seguretat Social).',
    fam_i2: 'Durant el permís Eurowings no paga el sou d’aquests dies: l’INSS paga el 100 % de la base reguladora (base de cotització del mes anterior ÷ 30, per dia), sense IRPF ni descomptes. Es demana a la seu electrònica de la Seguretat Social.',
    fam_i1: 'Permís per naixement: 19 setmanes per a cada progenitor. Les 6 primeres són obligatòries i seguides des del part; 11 més es poden agafar per setmanes fins que el nadó faci 12 mesos, i 2 més fins als 8 anys.',
