    fam_disc: 'This is an estimate with the 2026 rules. INSS calculates the exact amount: confirm it with HR or Social Security.',
    fam_i5: 'On the payslip a day of paid leave (like accumulated breastfeeding leave) counts like a leave day: 3:30 h FDP and 1:12 h additional duty (CLA art. 24.5.2 c and 24.5.3 b).',
    fam_i4: 'Breastfeeding: until the baby is 9 months old you have 1 paid hour off per day, or a half-hour shorter day. Crew usually accumulate it into full days; the CLA doesn’t cover it, so it is agreed with the company. If both parents take it equally, it can run until 12 months with reduced pay.',
    fam_i3: 'Pregnancy: as cabin crew you normally stop flying. If the company can’t offer a ground job, it is a suspension for risk during pregnancy and the mutual insurer pays 100 % of the regulatory base (this one does carry IRPF and social security).',
    fam_i2: 'During the leave Eurowings doesn’t pay salary for those days: INSS pays 100 % of your regulatory base (contribution base of the month before ÷ 30, per day), with no IRPF or deductions. You apply on the Social Security website.',
    fam_i1: 'Birth leave: 19 weeks for each parent. The first 6 are compulsory and straight after the birth; 11 more can be taken in weekly blocks until the baby is 12 months old, and 2 more until age 8.',
    fam_infoT: 'How it works',
    fam_lact: 'Breastfeeding leave runs until {d}. Returning on {b}, that is about {n} full days if you take it accumulated (1 h per working day).',
