    tool_map: 'Karte',
    fam_disc: 'Eine Schätzung nach den Regeln von 2026. Den genauen Betrag berechnet das INSS: bestätige ihn bei HR oder der Seguridad Social.',
    fam_i5: 'Auf der Abrechnung zählt ein bezahlter Freistellungstag (z. B. angesammelte Stillzeit) wie ein Urlaubstag: 3:30 h FDP und 1:12 h zusätzlicher Dienst (Tarifvertrag Art. 24.5.2 c und 24.5.3 b).',
    fam_i4: 'Stillzeit: Bis das Baby 9 Monate alt ist, hast du 1 bezahlte Stunde pro Tag frei oder eine halbe Stunde kürzeren Tag. Crews sammeln sie meist zu ganzen Tagen an; der Tarifvertrag regelt das nicht, also wird es mit der Firma vereinbart. Nehmen beide Eltern sie gleich, geht es mit weniger Gehalt bis 12 Monate.',
    fam_i3: 'Schwangerschaft: Als Kabinenpersonal fliegst du normalerweise nicht mehr. Kann dir die Firma keinen Bodenjob geben, ist es eine Freistellung wegen Risiko in der Schwangerschaft und die Mutua zahlt 100 % der Bemessungsgrundlage (mit IRPF und Sozialversicherung).',
    fam_i2: 'Während der Freistellung zahlt Eurowings für diese Tage kein Gehalt: Das INSS zahlt 100 % deiner Bemessungsgrundlage (Beitragsgrundlage des Vormonats ÷ 30 pro Tag), ohne IRPF und Abzüge. Der Antrag läuft über die Website der Seguridad Social.',
    fam_i1: 'Geburtsfreistellung: 19 Wochen pro Elternteil. Die ersten 6 sind Pflicht und direkt nach der Geburt; 11 weitere kannst du wochenweise bis zum 12. Lebensmonat nehmen und 2 weitere bis zum 8. Geburtstag.',
    fam_infoT: 'So funktioniert es',
