    fam_disc: 'C’est une estimation avec les règles 2026. Le montant exact est calculé par l’INSS : confirme-le avec les RH ou la Seguridad Social.',
    fam_i5: 'Sur la fiche de paie, un jour de congé payé (comme l’allaitement cumulé) compte comme un jour de vacances : 3:30 h de FDP et 1:12 h de service additionnel (convention, art. 24.5.2 c et 24.5.3 b).',
    fam_i4: 'Allaitement : jusqu’aux 9 mois du bébé, tu as 1 heure d’absence payée par jour, ou une demi-heure de moins. Les PNC le cumulent souvent en jours complets ; la convention ne le prévoit pas, cela se convient avec l’entreprise. Si les deux parents le prennent pareil, il peut aller jusqu’à 12 mois avec moins de salaire.',
    fam_i3: 'Grossesse : en tant que PNC tu arrêtes normalement de voler. Si l’entreprise ne peut pas t’offrir un poste au sol, c’est une suspension pour risque pendant la grossesse et la mutuelle verse 100 % de la base (avec IRPF et cotisations).',
    fam_i2: 'Pendant le congé, Eurowings ne paie pas le salaire de ces jours : l’INSS verse 100 % de ta base de calcul (base de cotisation du mois précédent ÷ 30, par jour), sans IRPF ni retenues. La demande se fait sur le site de la Seguridad Social.',
    fam_i1: 'Congé de naissance : 19 semaines par parent. Les 6 premières sont obligatoires et prises dès la naissance ; 11 autres se prennent par semaines jusqu’aux 12 mois du bébé, et 2 de plus jusqu’à ses 8 ans.',
