    fam_disc: 'Ez becslés a 2026-os szabályok alapján. A pontos összeget az INSS számolja ki: egyeztesd a HR-rel vagy a Seguridad Sociallal.',
    fam_i5: 'A bérjegyzéken egy fizetett távolléti nap (pl. összevont szoptatási nap) szabadságnapnak számít: 3:30 h FDP és 1:12 h kiegészítő szolgálat (szerződés 24.5.2 c és 24.5.3 b).',
    fam_i4: 'Szoptatás: a baba 9 hónapos koráig naponta 1 fizetett óra távollét jár, vagy fél órával rövidebb munkanap. A személyzet általában teljes napokba vonja össze; a kollektív szerződés nem szabályozza, ezért a céggel kell megállapodni. Ha mindkét szülő egyformán igénybe veszi, csökkentett fizetéssel 12 hónapig meghosszabbítható.',
    fam_i3: 'Terhesség: légiutas-kísérőként általában nem repülsz tovább. Ha a cég nem tud földi munkát adni, ez a terhesség alatti kockázat miatti felfüggesztés, és a mutua az alap 100 %-át fizeti (ez IRPF-et és járulékot is von).',
    fam_i2: 'A szabadság alatt az Eurowings ezekre a napokra nem fizet bért: az INSS a számítási alap 100 %-át fizeti (az előző havi járulékalap ÷ 30, naponta), IRPF és levonás nélkül. A Seguridad Social oldalán kell igényelni.',
    fam_i1: 'Születési szabadság: szülőnként 19 hét. Az első 6 kötelező, közvetlenül a szülés után; további 11 hetente vehető ki a baba 12 hónapos koráig, és még 2 a 8 éves koráig.',
