    fam_i4: 'Dojčenie: do 9 mesiacov dieťaťa máš 1 hodinu denne plateného voľna alebo o pol hodiny kratší deň. Posádky ho zvyčajne zlučujú do celých dní; kolektívna zmluva to neupravuje, takže sa to dohodne s firmou. Ak ho čerpajú obaja rodičia rovnako, dá sa predĺžiť do 12 mesiacov so zníženou mzdou.',
