    fam_disc: 'Je to odhad podle pravidel pro rok 2026. Přesnou částku počítá INSS: ověř si to s HR nebo se Seguridad Social.',
    fam_i5: 'Ve výplatě se den placeného volna (např. sloučené kojení) počítá jako den dovolené: 3:30 h FDP a 1:12 h dodatečné služby (smlouva čl. 24.5.2 c a 24.5.3 b).',
    fam_i4: 'Kojení: do 9 měsíců dítěte máš 1 hodinu denně placeného volna nebo o půl hodiny kratší den. Posádky ho obvykle slučují do celých dní; kolektivní smlouva to neupravuje, takže se to dohodne s firmou. Pokud ho čerpají oba rodiče stejně, lze ho prodloužit do 12 měsíců se sníženou mzdou.',
    fam_i3: 'Těhotenství: jako palubní průvodčí obvykle přestaneš létat. Pokud ti firma nemůže dát práci na zemi, jde o přerušení kvůli riziku v těhotenství a mutua platí 100 % základu (s IRPF a odvody).',
    fam_i2: 'Během volna Eurowings za ty dny neplatí mzdu: INSS platí 100 % vyměřovacího základu (odvodový základ předchozího měsíce ÷ 30, za den), bez IRPF a srážek. Žádá se na webu Seguridad Social.',
