    "fam_disc": "È una stima con le regole 2026. L’importo esatto lo calcola l’INSS: confermalo con le Risorse Umane o con la Seguridad Social.",
    "fam_i5": "In busta paga, un giorno di permesso retribuito (come l’allattamento accumulato) conta come un giorno di ferie: 3:30 h di FDP e 1:12 h di servizio aggiuntivo (contratto, art. 24.5.2 c e 24.5.3 b).",
    "fam_i4": "Allattamento: fino ai 9 mesi del bambino hai 1 ora al giorno di assenza retribuita, o mezz’ora in meno di lavoro. In volo di solito si accumula in giorni interi; il contratto non lo regola, quindi si concorda con l’azienda. Se lo usano entrambi i genitori allo stesso modo, si può estendere fino a 12 mesi con stipendio ridotto.",
    "fam_i3": "Gravidanza: come assistente di volo di solito smetti di volare. Se l’azienda non può darti un posto a terra, è una sospensione per rischio in gravidanza e la mutua paga il 100 % della base (con IRPF e contributi).",
    "fam_i2": "Durante il congedo Eurowings non paga lo stipendio di quei giorni: l’INSS paga il 100 % della base di calcolo (base contributiva del mese prima ÷ 30, al giorno), senza IRPF né trattenute. Si chiede sul sito della Seguridad Social.",
    "fam_i1": "Congedo di nascita: 19 settimane per ogni genitore. Le prime 6 sono obbligatorie e subito dopo il parto; altre 11 si possono prendere a settimane fino ai 12 mesi del bambino, e 2 in più fino agli 8 anni.",
