    "fam_disc": "É uma estimativa com as regras de 2026. O valor exato é calculado pelo INSS: confirma com os RH ou com a Seguridad Social.",
    "fam_i5": "No recibo, um dia de licença paga (como a amamentação acumulada) conta como um dia de férias: 3:30 h de FDP e 1:12 h de serviço adicional (convénio, art. 24.5.2 c e 24.5.3 b).",
    "fam_i4": "Amamentação: até o bebé fazer 9 meses tens 1 hora por dia de ausência paga, ou meia hora a menos de jornada. Em voo o habitual é acumulá-la em dias completos; o convénio não o regula, por isso combina-se com a empresa. Se os dois progenitores a gozarem igual, pode ir até aos 12 meses com menos salário.",
