    "fam_i5": "Pe fluturaș, o zi de învoire plătită (ca alăptarea cumulată) contează ca o zi de concediu: 3:30 h FDP și 1:12 h serviciu suplimentar (contract, art. 24.5.2 c și 24.5.3 b).",
    "fam_i4": "Alăptare: până la 9 luni ale copilului ai 1 oră pe zi de absență plătită sau o jumătate de oră mai puțin. Echipajele o cumulează de obicei în zile întregi; contractul colectiv nu o reglementează, deci se convine cu firma. Dacă ambii părinți o iau la fel, se poate prelungi până la 12 luni cu salariu redus.",
    "fam_i3": "Sarcină: ca însoțitor de bord de obicei nu mai zbori. Dacă firma nu îți poate da un post la sol, e o suspendare pentru risc în sarcină și mutua plătește 100 % din bază (cu IRPF și asigurări).",
